def _markdown(text,role,**metadata):
    cell=nb.v4.new_markdown_cell(text)
    cell.metadata['teaching']={'role':role,**metadata}
    return cell


def enrich(cells):
    """Add explanations; split figures into separate readable units, not new analyses."""
    result=[];block=0
    for index,cell in enumerate(cells):
        if index==0:
            result.append(_markdown(INTRO,'introduction'));continue
        if cell.cell_type!='code':result.append(cell);continue
        block+=1;before,after=BLOCKS[block]
        result.append(_markdown(before,'before_block',block=block))
        pending=[]
        def flush():
            if pending:
                if result[-1].metadata.get('teaching',{}).get('role')=='after_figure':
                    notes={
                        7:'**Следующая таблица уточняет причины неуспеха.** Она считает статусы формата по моделям: разрешённая Markdown-оболочка, повреждённый JSON или незавершённый ответ. Эти количества помогают понять, почему ответ не попал в число верных; содержание и интерфейсный формат не смешиваются.',
                        14:'**Далее — отдельная диагностика кода Giga.** Читаются прежние результаты запуска извлечённых фрагментов, а не запускается новый код. Эта таблица помогает отличить ошибку оформления ответа от runtime-ошибки программы и не изменяет первичную оценку 0/8.',
                        17:'**Далее — сведения о локальной машине и памяти.** Из сохранённого мониторинга выводятся CPU, RAM, пиковый RSS процесса и память всего GPU. Значения в bytes нужно делить на 1024³ для GiB; sampled peak означает максимум среди измерений, а не гарантированный непрерывный пик.'}
                    result.append(_markdown(notes[block],'before_subblock',block=block))
                new=nb.v4.new_code_cell('\n'.join(pending));new.metadata['teaching_block']=block;result.append(new);pending.clear()
        for line in cell.source.splitlines():
            match=re.fullmatch(r"figure\('([^']+)'\)",line.strip())
            if not match:pending.append(line);continue
            flush();name=match.group(1);intro,interpretation=FIGURES[name]
            result.append(_markdown(intro,'before_figure',figure=name))
            new=nb.v4.new_code_cell(line);new.metadata['teaching_block']=block;new.metadata['teaching_figure']=name;result.append(new)
            result.append(_markdown(interpretation,'after_figure',figure=name))
        flush()
        result.append(_markdown(after,'after_block',block=block))
    assert block==len(BLOCKS),'Original computation blocks changed; update their explanations'
    return result
